package mz.bam.seeky.android;
import android.content.*;import android.database.Cursor;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;

/** Cleanup is conservative: unreadable recovery metadata prevents orphan deletion. */
final class StorageReview {
    static final class Protection {final Set<String> files=new HashSet<>(),archiveFiles=new HashSet<>();final List<String> folders=new ArrayList<>();void file(File f)throws IOException{files.add(f.getCanonicalPath());}void folder(File f)throws IOException{folders.add(f.getCanonicalPath()+File.separator);}boolean keeps(File f)throws IOException{String path=f.getCanonicalPath();if(files.contains(path))return true;for(String prefix:folders)if(path.startsWith(prefix))return true;return false;}}
    static List<File> files(File root)throws IOException{List<File> result=new ArrayList<>();if(!root.exists())return result;try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){paths.filter(p->Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)).forEach(p->result.add(p.toFile()));}return result;}
    static long bytes(Collection<File> files){long n=0;for(File f:files)n+=f.length();return n;}
    static Protection protection(Context c)throws Exception{Protection p=new Protection();try(StudyStore db=new StudyStore(c);Cursor rows=db.getReadableDatabase().query("materials",new String[]{"path"},null,null,null,null,null)){while(rows.moveToNext())p.file(new File(rows.getString(0)));}
        try(PlusStore db=new PlusStore(c);Cursor rows=db.getReadableDatabase().query("voice_notes",new String[]{"path"},null,null,null,null,null)){while(rows.moveToNext())p.file(new File(rows.getString(0)));}
        try(PlusStore db=new PlusStore(c);Cursor rows=db.getReadableDatabase().query("audio_tracks",new String[]{"uri"},null,null,null,null,null)){while(rows.moveToNext()){Uri uri=Uri.parse(rows.getString(0));if("file".equals(uri.getScheme()))p.file(new File(uri.getPath()));}}
        for(NarrationJob job:NarrationJob.list(c,null)){String background=job.s("background");if(!background.isEmpty())p.file(new File(background));}
        String current=c.getSharedPreferences("reading_background",0).getString("path","");if(!current.isEmpty())p.file(new File(current));for(File file:BookSettings.activeFiles(c)){p.file(file);JSONObject data=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));String cover=data.optString("cover","");if(!cover.isEmpty())p.file(new File(cover));JSONObject profile=data.optJSONObject("profile");if(profile!=null&&!profile.optString("background_path").isEmpty())p.file(new File(profile.getString("background_path")));}
        for(File f:new SeekyAiStore(c).activeFiles())p.file(f);
        try(TaskStore db=new TaskStore(c);Cursor rows=db.getReadableDatabase().query("jobs",new String[]{"id","type","state","payload"},null,null,null,null,null)){while(rows.moveToNext()){String id=rows.getString(0),type=rows.getString(1),state=rows.getString(2);JSONObject data=new JSONObject(rows.getString(3));boolean retained=!state.equals("complete")||type.equals("summary");if(!retained)continue;p.folder(new File(c.getCacheDir(),"backup-work-"+id));p.folder(new File(new File(c.getFilesDir(),"work-content"),id));String stage=data.optString("staged","");if(!stage.isEmpty())p.folder(new File(stage));String source=data.optString("snapshot","");if(!source.isEmpty())p.file(new File(source));try(Cursor items=db.getReadableDatabase().query("items",new String[]{"target"},"job=? AND target<>''",new String[]{id},null,null,null)){while(items.moveToNext()){File f=new File(items.getString(0));p.file(f);p.file(new File(f.getPath()+".part"));}}}}
        File recovery=new File(c.getFilesDir(),"workspace-recovery");File[] archives=recovery.listFiles((d,n)->n.endsWith(".zip"));if(archives!=null)for(File archive:archives){try(ZipFile zip=new ZipFile(archive)){ZipEntry entry=zip.getEntry("workspace.json");if(entry==null)throw new IOException("Uma recuperação não pôde ser verificada. A limpeza foi interrompida.");String raw;try(InputStream in=zip.getInputStream(entry)){raw=new String(ContentText.read(in,16777217),StandardCharsets.UTF_8);}if(raw.length()>16777216)throw new IOException("Recuperação demasiado extensa para verificar a limpeza.");JsonBudget.check(raw,14,250000);JSONArray entries=new JSONObject(raw).getJSONArray("entries");for(int i=0;i<entries.length();i++){JSONObject item=entries.getJSONObject(i);if(item.optString("kind").equals("file")){String path=new File(item.getString("path")).getCanonicalPath();p.files.add(path);p.archiveFiles.add(path);}}}catch(Exception e){throw new IOException("Não foi possível verificar uma recuperação anterior. Nenhum ficheiro sem ligação foi eliminado.",e);}}
        for(android.app.Activity active:WorkLeases.snapshot())if(active instanceof ApkInstallActivity&&((ApkInstallActivity)active).prepared!=null)p.file(((ApkInstallActivity)active).prepared);for(android.app.Activity active:WorkLeases.snapshot())if(active instanceof LibraryBatchActivity&&((LibraryBatchActivity)active).selectionFile!=null)p.file(((LibraryBatchActivity)active).selectionFile);if(WorkspaceBackup.pending(c).isFile())throw new IOException("Termine a recuperação antes de limpar ficheiros.");return p;
    }
    static List<File> unused(Context c)throws Exception{Protection p=protection(c);List<File> out=new ArrayList<>();for(String folder:new String[]{"study-materials","voice-notes","backgrounds","book-settings","book-covers","seeky-ai-conversations","narrations","work-sources","work-content"})for(File f:files(new File(c.getFilesDir(),folder)))if(!p.keeps(f))out.add(f);return out;}
    static List<File> cache(Context c)throws Exception{if(WorkLeases.readerOpen()||SpeechEvents.state.active||NarrationExportService.running)return Collections.emptyList();Protection p=protection(c);List<File> out=new ArrayList<>();for(File f:files(c.getCacheDir()))if(!p.keeps(f))out.add(f);return out;}
    static void delete(Context c,Collection<File> selected,boolean cache)throws Exception{if(WorkspaceEpoch.restoring||TaskService.instance!=null&&TaskService.instance.current!=null&&TaskService.instance.current.critical)throw new IOException("Aguarde a recuperação terminar.");Set<String> allowed=new HashSet<>();for(File f:cache?cache(c):unused(c))allowed.add(f.getCanonicalPath());for(File candidate:selected){File f=candidate.getCanonicalFile();if(!allowed.contains(f.getPath()))continue;if(!DiskWalker.inside((cache?c.getCacheDir():c.getFilesDir()).getCanonicalFile(),f))throw new IOException("Ficheiro de limpeza inválido.");Files.deleteIfExists(f.toPath());}}
    private StorageReview(){}
}
